// deadUpstream returns a GET spec whose URL points at a loopback port nothing
// listens on (a listener opened and closed — the fetch_test.go network-class
// upstream): the dial dies with connection refused and no HTTP response ever
// arrives, the canonical network-class failure. Create any live httptest
// server BEFORE calling this — the OS must never hand the dead port to a
// server bound afterward.
func deadUpstream(t *testing.T) *metadatav1.RequestSpec {
	t.Helper()
	lis, err := net.Listen("tcp", "127.0.0.1:0")
	if err != nil {
		t.Fatalf("listen: %v", err)
	}
	port := lis.Addr().(*net.TCPAddr).Port
	_ = lis.Close()
	return &metadatav1.RequestSpec{Method: "GET", UrlTemplate: fmt.Sprintf("https://127.0.0.1:%d/blocked", port)}
}

// runDeferred drives one runSourceRetryable over the plan source with the
// queue-shaped knobs the dispatch passes (3 attempts, 1ms backoff) and the
// given relay scope, returning the raw outcome triple.
func runDeferred(src *planSource, sc *relayScope) (sourceResult, string, int) {
	mod := module.Module{ID: "serial", MediaType: "serial", MetadataSources: []module.MetadataSourceBinding{binding("plan", 1, true)}}
	return runSourceRetryable(context.Background(), resolverOf(src, nil), binding("plan", 1, true), mod, &scannerv1.IdentifyResult{}, map[string]any{}, nil, sc, 3, time.Millisecond)
}

// runScopedSource drives one bare runSource (no retry loop, no gate) over the
// plan source under the given relay scope.
func runScopedSource(src *planSource, sc *relayScope) sourceResult {
	mod := module.Module{ID: "serial", MediaType: "serial"}
	return runSource(context.Background(), resolverOf(src, nil), binding("plan", 1, true), mod, &scannerv1.IdentifyResult{}, map[string]any{}, nil, sc)
}

// relayConsumed reads the consumed flag straight off the job row (the S10
// seam — no store read method exposes it).
func relayConsumed(t *testing.T, s *store.Store, id int64) bool {
	t.Helper()
	var consumed bool
	if err := s.DB().QueryRowContext(context.Background(), "SELECT consumed FROM relay_jobs WHERE id = ?", id).Scan(&consumed); err != nil {
		t.Fatalf("consumed read %d: %v", id, err)
	}
	return consumed
}

// assertDeferredJob claims the run's handoff back and asserts the whole-plan
// positional shape and the (row, plugin) identity a 3.2 handoff must carry.
func assertDeferredJob(t *testing.T, s *store.Store, rowID string, libraryID int64, wantURLs []string) relay.RelayJob {
	t.Helper()
	job, found := relayClaim(t, s)
	if !found {
		t.Fatal("no relay job after the deferred run")
	}
	if job.Purpose != relayPurposeEnrich || job.RowID != rowID || job.LibraryID != libraryID || job.PluginID != "plan" {
		t.Fatalf("job identity = %s/%s/%d/%s, want enrich/%s/%d/plan", job.Purpose, job.RowID, job.LibraryID, job.PluginID, rowID, libraryID)
	}
	if len(job.Plan) != len(wantURLs) {
		t.Fatalf("plan len = %d, want %d (the WHOLE plan, positional)", len(job.Plan), len(wantURLs))
	}
	for i, want := range wantURLs {
		if job.Plan[i].Method != "GET" || job.Plan[i].URL != want {
			t.Fatalf("plan[%d] = %s %s, want GET %s (positional: primary first, extras after)", i, job.Plan[i].Method, job.Plan[i].URL, want)
		}
	}
	return job
}

// assertRelayedRow asserts the ledger carries exactly one relayed row for the
// pair with the class-token reason and the given round counter (attempts == 1
// proves the handoff ran exactly once — a retry-loop rerun would enqueue twice).
func assertRelayedRow(t *testing.T, s *store.Store, rowID string, wantAttempts int) store.FailureRow {
	t.Helper()
	rows, err := s.ListFailures(context.Background())
	if err != nil {
		t.Fatalf("ListFailures: %v", err)
	}
	if len(rows) != 1 {
		t.Fatalf("ledger rows = %d, want 1 (the relayed row IS the only loop-safety write)", len(rows))
	}
	row := rows[0]
	if row.Status != relayedStatus || row.ItemID != rowID || row.PluginID != "plan" {
		t.Fatalf("row = %s/%s/%s, want relayed/%s/plan", row.Status, row.ItemID, row.PluginID, rowID)
	}
	if !strings.HasPrefix(row.Reason, fetchClassNetwork+": ") {
		t.Fatalf("reason = %q, want the %q class-token prefix", row.Reason, fetchClassNetwork)
	}
	if row.Attempts != wantAttempts {
		t.Fatalf("attempts = %d, want %d (exactly one handoff)", row.Attempts, wantAttempts)
	}
	return row
}

// TestDeferredHandoff is client-relayed-fetch task 3.2's handoff table: a
// network-class failure on the primary OR any extra converts the run to the
// deferred outcome (neither failed nor succeeded) at the runSource call site
// and hands the WHOLE plan positionally to the relay; runSourceRetryable
// short-circuits it (no backoff, no exhausted write); a nil Relay keeps
// today's failure behavior bit-identical.
func TestDeferredHandoff(t *testing.T) {
	ctx := context.Background()

	t.Run("network primary defers the whole plan: one job, positional, retry short-circuits", func(t *testing.T) {
		s := relayTestStore(t)
		r := &Relay{Store: s}
		rec := &fetchRecorder{}
		live := httptest.NewServer(rec)
		defer live.Close()
		dead := deadUpstream(t) // after the live bind: the OS cannot rebind the dead port
		src := &planSource{
			primary: dead,
			extras:  []*metadatav1.RequestSpec{{Method: "GET", UrlTemplate: live.URL + "?which=extra1"}},
		}
		sc := &relayScope{relay: r, rowID: "itm_d1", libraryID: 7}
		sr, ledgerStatus, attempts := runDeferred(src, sc)

		if sr.kind != outcomeDeferred {
			t.Fatalf("kind = %v (err %q), want deferred (neither failed nor succeeded)", sr.kind, sr.errMsg)
		}
		if ledgerStatus != "" {
			t.Fatalf("ledgerStatus = %q, want empty (no exhausted write — the relayed row IS the loop-safety write)", ledgerStatus)
		}
		if attempts != 1 {
			t.Fatalf("attempts = %d, want 1 (short-circuit: no backoff, no second attempt of 3)", attempts)
		}
		if src.converted {
			t.Fatal("Convert ran on a deferred run; the run must end at the handoff")
		}
		if n := rec.count(); n != 0 {
			t.Fatalf("upstream saw %d requests, want 0 (the extras never fetch server-side once the run defers)", n)
		}
		assertDeferredJob(t, s, "itm_d1", 7, []string{dead.GetUrlTemplate(), live.URL + "?which=extra1"})
		assertRelayedRow(t, s, "itm_d1", 1)
		// The deferred _stages entry: deferred status beside the machine class.
		doc := map[string]any{}
		appendStage(doc, sr, "pending")
		st := stages(doc)
		if len(st) != 1 || st[0]["status"] != "deferred" || st[0]["class"] != fetchClassNetwork {
			t.Fatalf("stage = %v, want status %q with class %q", st, "deferred", fetchClassNetwork)
		}
		if _, has := st[0]["executor"]; has {
			t.Fatal("deferred stage carries executor; nothing ran client-side yet")
		}
	})

	t.Run("network extra defers too: the plan hands whole before any soft-fail", func(t *testing.T) {
		s := relayTestStore(t)
		r := &Relay{Store: s}
		rec := &fetchRecorder{}
		live := httptest.NewServer(rec)
		defer live.Close()
		dead := deadUpstream(t)
		src := &planSource{
			primary: &metadatav1.RequestSpec{Method: "GET", UrlTemplate: live.URL + "?which=primary"},
			extras: []*metadatav1.RequestSpec{
				dead, // the network-class failure
				// fetchExtras' flow is today's (each extra attempted, entries
				// soft-fail); the DEFERRAL converts the outcome afterward —
				// so the trailing extra still fetches server-side this round.
				{Method: "GET", UrlTemplate: live.URL + "?which=extra2"},
			},
		}
		sc := &relayScope{relay: r, rowID: "itm_d2", libraryID: 7}
		sr, ledgerStatus, attempts := runDeferred(src, sc)

		if sr.kind != outcomeDeferred || ledgerStatus != "" || attempts != 1 {
			t.Fatalf("outcome = %v/%q/%d, want deferred/\"\"/1 (the extra failure defers with the same short-circuit)", sr.kind, ledgerStatus, attempts)
		}
		if src.converted {
			t.Fatal("Convert ran on a deferred run; the extra's failure must defer, not soft-fail the entry")
		}
		// The primary and the trailing extra fetched; the dead extra refused.
		if n := rec.count(); n != 2 {
			t.Fatalf("upstream saw %d requests, want 2 (primary + trailing extra; the dead extra never hit)", n)
		}
		assertDeferredJob(t, s, "itm_d2", 7, []string{
			live.URL + "?which=primary", dead.GetUrlTemplate(), live.URL + "?which=extra2",
		})
		assertRelayedRow(t, s, "itm_d2", 1)
	})

	t.Run("nil relay passthrough: today's failure behavior bit-identical", func(t *testing.T) {
		s := relayTestStore(t)
		live := httptest.NewServer(&fetchRecorder{})
		defer live.Close()
		dead := deadUpstream(t)
		for _, sc := range []*relayScope{nil, {rowID: "itm_d3", libraryID: 7}} { // nil scope AND nil relay inside: both disabled
			src := &planSource{primary: dead}
			sr, ledgerStatus, attempts := runDeferred(src, sc)
			if sr.kind != outcomeFailed {
				t.Fatalf("scope %+v: kind = %v, want failed (today's behavior)", sc, sr.kind)
			}
			if ledgerStatus != ledgerExhausted || attempts != 3 {
				t.Fatalf("scope %+v: ledgerStatus/attempts = %q/%d, want exhausted/3 (the normal retry loop ran)", sc, ledgerStatus, attempts)
			}
			if src.converted {
				t.Fatalf("scope %+v: Convert ran after a failed primary", sc)
			}
		}
		// The disabled relay wrote nothing anywhere.
		if rows, err := s.ListFailures(ctx); err != nil || len(rows) != 0 {
			t.Fatalf("ledger rows = %d (err %v), want 0", len(rows), err)
		}
		if _, found := relayClaim(t, s); found {
			t.Fatal("a relay job exists under a disabled relay")
		}
	})

	t.Run("enqueue error degrades to today's failure", func(t *testing.T) {
		s := relayTestStore(t)
		_ = s.Close() // the relay store is broken
		r := &Relay{Store: s}
		live := httptest.NewServer(&fetchRecorder{})
		defer live.Close()
		dead := deadUpstream(t)
		src := &planSource{primary: dead}
		sr, ledgerStatus, attempts := runDeferred(src, &relayScope{relay: r, rowID: "itm_d4", libraryID: 7})
		if sr.kind != outcomeFailed || ledgerStatus != ledgerExhausted || attempts != 3 {
			t.Fatalf("outcome = %v/%q/%d, want failed/exhausted/3 (the soft-fail falls back to today's path)", sr.kind, ledgerStatus, attempts)
		}
	})
}

// TestDeferredConsultFeedsConvert is task 3.2's consult table: the fetch path
// consults Relay.Consult BEFORE fetching — a done, unconsumed, plan-matched
// job feeds its stored response into Convert exactly as a server fetch, is
// consumed, and the consuming run's _stages fetch entry is stamped
// executor:"client"; a plan mismatch misses the cache and fetches normally.
func TestDeferredConsultFeedsConvert(t *testing.T) {
	ctx := context.Background()

	t.Run("consult hit feeds Convert exactly as a server fetch, stamped executor client", func(t *testing.T) {
		s := relayTestStore(t)
		r := &Relay{Store: s}
		rec := &fetchRecorder{}
		live := httptest.NewServer(rec)
		defer live.Close()
		dead := deadUpstream(t) // the hit must precede any fetch: were the cache missed, the dial dies
		primary := dead
		extra := &metadatav1.RequestSpec{Method: "GET", UrlTemplate: live.URL + "?which=extra1"}
		var gotConv *metadatav1.ConvertRequest
		src := &planSource{
			primary:   primary,
			extras:    []*metadatav1.RequestSpec{extra},
			onConvert: func(cr *metadatav1.ConvertRequest) { gotConv = cr },
		}

		// Seed a done, unconsumed, plan-MATCHED job: hand off, claim, ingest done.
		sc := &relayScope{relay: r, rowID: "itm_c1", libraryID: 3}
		plan := buildPlan(primary, []*metadatav1.RequestSpec{extra})
		if err := r.Enqueue(ctx, plan, relayPurposeEnrich, "itm_c1", 3, "plan", fetchClassNetwork, "dial tcp: refused"); err != nil {
			t.Fatalf("Enqueue: %v", err)
		}
		job, found := relayClaim(t, s)
		if !found {
			t.Fatal("seed handoff produced no claimable job")
		}
		stored := relay.RelayResult{
			HTTPStatus: 200,
			Headers:    map[string]string{"X-Relay": "client-1", "Content-Type": "application/json"},
			Body:       []byte(`{"id":1,"name":"stored-by-client"}`),
		}
		if err := r.Ingest(ctx, job.ID, "test-principal", stored); err != nil {
			t.Fatalf("Ingest: %v", err)
		}

		sr := runScopedSource(src, sc)
		if sr.kind != outcomeSucceeded {
			t.Fatalf("kind = %v (err %q), want succeeded off the consult hit", sr.kind, sr.errMsg)
		}
		if !src.converted || gotConv == nil {
			t.Fatal("Convert never ran on the consult hit")
		}
		// The stored response rides the PRIMARY slot exactly as a server fetch.
		if string(gotConv.GetRawResponse()) != string(stored.Body) {
			t.Fatalf("raw_response = %q, want the stored body %q", gotConv.GetRawResponse(), stored.Body)
		}
		if gotConv.GetHttpStatus() != int32(stored.HTTPStatus) {
			t.Fatalf("http_status = %d, want %d", gotConv.GetHttpStatus(), stored.HTTPStatus)
		}
		if gotConv.GetResponseHeaders()["X-Relay"] != "client-1" {
			t.Fatalf("response_headers[X-Relay] = %v, want client-1", gotConv.GetResponseHeaders())
		}
		// The extra fetched server-side beside the cached primary (positional).
		if n := rec.count(); n != 1 {
			t.Fatalf("upstream saw %d requests, want 1 (the extra only — no second fetch of the primary's URL)", n)
		}
		if extras := gotConv.GetExtraResponses(); len(extras) != 1 || !extras[0].GetFetched() {
			t.Fatalf("extra_responses = %v, want one fetched entry", extras)
		}
		// The consuming run's _stages fetch entry carries the executor stamp.
		if sr.executor != executorClient {
			t.Fatalf("sr.executor = %q, want %q", sr.executor, executorClient)
		}
		doc := map[string]any{}
		appendStage(doc, sr, "enriched")
		st := stages(doc)
		if len(st) != 1 || st[0]["status"] != "ok" {
			t.Fatalf("stage = %v, want status ok", st)
		}
		if st[0]["executor"] != executorClient {
			t.Fatalf("stage executor = %v, want %q", st[0]["executor"], executorClient)
		}
		if !relayConsumed(t, s, job.ID) {
			t.Fatal("the feeding consult did not consume the job")
		}
	})

	t.Run("mismatched plan misses the cache and degrades to a server fetch", func(t *testing.T) {
		s := relayTestStore(t)
		r := &Relay{Store: s}
		rec := &fetchRecorder{}
		live := httptest.NewServer(rec)
		defer live.Close()
		primary := &metadatav1.RequestSpec{Method: "GET", UrlTemplate: live.URL + "?which=fresh"}
		var gotConv *metadatav1.ConvertRequest
		src := &planSource{
			primary:   primary,
			onConvert: func(cr *metadatav1.ConvertRequest) { gotConv = cr },
		}

		// A done, unconsumed job whose plan NO LONGER matches (the document
		// drifted): the stale job must stay unconsumed.
		stalePlan := []relay.PlanSpec{{Method: "GET", URL: "https://stale.example/old", TimeoutSeconds: 5}}
		if err := r.Enqueue(ctx, stalePlan, relayPurposeEnrich, "itm_c2", 3, "plan", fetchClassNetwork, "dial tcp: refused"); err != nil {
			t.Fatalf("Enqueue: %v", err)
		}
		job, found := relayClaim(t, s)
		if !found {
			t.Fatal("seed handoff produced no claimable job")
		}
		if err := r.Ingest(ctx, job.ID, "test-principal", relay.RelayResult{HTTPStatus: 200, Body: []byte(`{"stale":true}`)}); err != nil {
			t.Fatalf("Ingest: %v", err)
		}

		sr := runScopedSource(src, &relayScope{relay: r, rowID: "itm_c2", libraryID: 3})
		if sr.kind != outcomeSucceeded {
			t.Fatalf("kind = %v (err %q), want succeeded via the normal server fetch", sr.kind, sr.errMsg)
		}
		if n := rec.count(); n != 1 {
			t.Fatalf("upstream saw %d requests, want 1 (the mismatch fetched server-side)", n)
		}
		if string(gotConv.GetRawResponse()) != `{"id":1,"n":1}` {
			t.Fatalf("raw_response = %q, want the LIVE body (not the stale stored one)", gotConv.GetRawResponse())
		}
		if sr.executor != "" {
			t.Fatalf("sr.executor = %q, want empty (a server fetch)", sr.executor)
		}
		doc := map[string]any{}
		appendStage(doc, sr, "enriched")
		st := stages(doc)
		if len(st) != 1 || st[0]["status"] != "ok" {
			t.Fatalf("stage = %v, want status ok", st)
		}
		if _, has := st[0]["executor"]; has {
			t.Fatal("mismatched-plan run stamped executor; the fetch ran server-side")
		}
		if relayConsumed(t, s, job.ID) {
			t.Fatal("the stale job was consumed by a mismatched consult")
		}
	})
}
